<?php

declare(strict_types=1);

namespace Wcp360\Core\Module\Hosting\Domain;

/** Fixed public syntax evidence bound to exact generated bytes, never activation authority. */
final class ApplicationSyntaxReport
{
    /** @param array<array-key,mixed> $statuses
     * @return array<string,mixed>
     */
    public static function build(ApplicationPlanDocument $document, bool $requested, array $statuses = []): array
    {
        $files = $document->files();
        if (($requested && array_keys($statuses) !== array_keys($files)) || (!$requested && $statuses !== [])) {
            throw new \InvalidArgumentException('Invalid syntax check envelope.');
        }
        $checks = [];
        foreach ($files as $artifact => $file) {
            $status = $requested ? $statuses[$artifact] : 'not_run';
            if (!in_array($status, ['passed', 'failed', 'not_configured', 'not_run'], true)) {
                throw new \InvalidArgumentException('Invalid syntax check status.');
            }
            [$tool, $stage] = match ($artifact) {
                'nginx' => ['nginx', 'configuration_test'],
                'caddy' => [$document->fields()['application_server'] === 'frankenphp_classic' ? 'frankenphp' : 'caddy', 'caddyfile_adaptation'],
                'apache' => ['apache', 'configuration_test'],
                'php_fpm' => ['php_fpm', 'synthetic_pool_identity'],
                'htaccess' => ['apache', 'request_rewrite_execution'],
                'systemd_unit' => ['systemd', 'unit_verification'],
                default => throw new \LogicException('Unknown syntax artifact.'),
            };
            $checks[] = ['artifact' => $artifact, 'sha256' => hash('sha256', $file['content']),
                'tool' => $tool, 'stage' => $stage, 'status' => $status];
        }
        return ['schema' => 'wcp360.candidate.application-syntax/1', 'requested' => $requested,
            'coverage_complete' => false, 'activation_authorized' => false, 'runtime_validated' => false, 'checks' => $checks];
    }
}
